using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class RoutRegroupTests
{
    static void At(WorldSession s,long t)=>NewGameWorldTests.At(s,t);
    static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
    static NewMilitaryInput I(WorldSession s,NewMilitaryAction a)=>new(new("request:rout-test/"+s.Revision+"/"+a),a);
    static void Send(WorldSession s,NewMilitaryAction a,long amount=0){var r=s.DecideNewMilitary(I(s,a) with{Amount=amount},s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
    static WorldSession Ready(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);Send(s,NewMilitaryAction.Request);At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);Send(s,NewMilitaryAction.CombatPermit);At(s,s.Seconds+2);Open(s);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(I(s,NewMilitaryAction.Form) with{A=new(a.X+30000,a.Y),B=new(a.X+30000,a.Y+16000)},s.PlayerControl,s.Revision).Code);At(s,s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.Max(r=>r.LastOrDefault()?.EndAt??s.Seconds)+1);return s;}
    static NewMilitaryInput RoutInput(WorldSession s)=>I(s,NewMilitaryAction.CombatStart) with{MotionContract=NewGameMilitary.RoutContract};
    static WorldSession Contact(){var s=Ready();var r=s.DecideNewMilitary(RoutInput(s),s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);return s;}
    static long ArmyEnd(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.SelectMany(r=>r).Select(l=>l.EndAt).DefaultIfEmpty(s.Seconds).Max();
    [Fact]public void RoutRequiresOpenedCombatPermission(){var s=Ready();At(s,s.Seconds+121);Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(RoutInput(s),s.PlayerControl,s.Revision).Code);}
    [Fact]public void OldContactDoesNotAcquireNewSavedRules(){var s=Ready();Send(s,NewMilitaryAction.CombatStart);At(s,s.Seconds+12);Assert.Null(s.DiagnosticSnapshot().NewMilitary!.Rout);Assert.DoesNotContain("\"Rout\"",System.Text.Encoding.UTF8.GetString(ContractJson.Write(s.DiagnosticSnapshot().NewMilitary)));}
    [Fact]public void NoRetreatBeforeMoraleThreshold(){var s=Contact();At(s,s.Seconds+9);Assert.Empty(s.DiagnosticSnapshot().NewMilitary!.Rout!.Retreats);}
    [Fact]public void CollapseCreatesPhysicalRoutesWithoutDeletingPeople(){var s=Contact();At(s,s.Seconds+10);var w=s.DiagnosticSnapshot();Assert.Single(w.NewMilitary!.Rout!.Retreats);Assert.All(Enumerable.Range(0,3),i=>Assert.Equal("routed",NewGameMilitary.RoutPhase(w,i)));Assert.All(w.Characters,c=>Assert.Equal(LifeState.Adult,c.Life));Assert.True(NewGameMilitary.Moving(w));}
    [Fact]public void PersonalWithdrawalStaysIndependentOfAutomaticRout(){var s=Contact();Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);At(s,s.Seconds+10);var w=s.DiagnosticSnapshot();Assert.True(NewGameMilitary.Detached(w));Assert.NotEqual(NewGameMilitary.PersonPosition(w,s.Seconds),NewGameMilitary.Position(w,0,s.Seconds));Assert.Equal(NewGameMilitary.UnitIds[0],w.ResourceLots.Single(l=>l.Id==NewGameMilitary.Carry).MobileHolder);}
    [Fact]public void ArrivalAndRegroupingAreDifferentEvents(){var s=Contact();At(s,s.Seconds+10);At(s,ArmyEnd(s));var w=s.DiagnosticSnapshot();Assert.Equal(3,w.NewMilitary!.Rout!.Arrivals.Length);Assert.Empty(w.NewMilitary.Rout.Regroups);Assert.True(NewGameMilitary.RoutActive(w));At(s,s.Seconds+NewGameMilitary.RegroupSeconds);Assert.Equal(3,s.DiagnosticSnapshot().NewMilitary!.Rout!.Regroups.Length);Assert.False(NewGameMilitary.RoutActive(s.DiagnosticSnapshot()));}
    [Fact]public void RegroupDoesNotResurrectCasualties(){var s=Contact();At(s,s.Seconds+10);int men=NewGameMilitary.TotalStrength(s.DiagnosticSnapshot(),s.Seconds);At(s,ArmyEnd(s)+NewGameMilitary.RegroupSeconds+1);Assert.Equal(men,NewGameMilitary.TotalStrength(s.DiagnosticSnapshot(),s.Seconds));Assert.All(Enumerable.Range(0,3),i=>Assert.Equal(NewGameMilitary.RegroupMorale,NewGameMilitary.RegroupedMorale(s.DiagnosticSnapshot(),i)));}
    [Fact]public void NoInstantFormationOrHandoverDuringRegroup(){var s=Contact();At(s,s.Seconds+10);foreach(var a in new[]{NewMilitaryAction.Hold,NewMilitaryAction.Enter})Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(I(s,a),s.PlayerControl,s.Revision).Code);}
    [Fact]public void RepeatedInputCannotDuplicateRout(){var s=Ready();var i=RoutInput(s);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);At(s,s.Seconds+12);Assert.Equal(ResultCode.AlreadyAccepted,s.DecideNewMilitary(i,s.PlayerControl,0).Code);Assert.Single(s.DiagnosticSnapshot().NewMilitary!.Rout!.Retreats);}
    [Theory][InlineData(1)][InlineData(9)][InlineData(10)][InlineData(11)][InlineData(30)][InlineData(70)]public void SaveRestorationPreservesRoutAndRegroupFuture(int offset){var s=Contact();At(s,s.Seconds+offset);var copy=new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));long until=s.Seconds+150;foreach(var x in new[]{s,copy})At(x,until);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(copy.DiagnosticSnapshot()));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void ForgedRoutHistoryIsRejected(int kind){var s=Contact();At(s,s.Seconds+10);var w=s.DiagnosticSnapshot();var r=w.NewMilitary!.Rout!;if(kind==0)r.Retreats[0]=r.Retreats[0] with{At=r.Retreats[0].At-1};if(kind==1)r.Retreats[0]=r.Retreats[0] with{Units=[0]};if(kind==2){var o=w.NewMilitary.Orders.Last();o.Routes[0][0]=o.Routes[0][0] with{EndAt=o.Routes[0][0].EndAt-1};}Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void MissingRoutDecisionCannotBeLoaded(){var s=Contact();At(s,s.Seconds+10);var w=s.DiagnosticSnapshot();w.NewMilitary=w.NewMilitary! with{Rout=w.NewMilitary.Rout! with{Retreats=[]}};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void OwnershipAndDefinitionsRemainUnchanged(){var s=Contact();string hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot().Definitions);At(s,s.Seconds+150);var w=s.DiagnosticSnapshot();Assert.Equal(hash,ContractJson.CanonicalHash(w.Definitions));Assert.All(w.Units,u=>Assert.Equal(w.NewMilitary!.Terms.Owner,u.Organization));Assert.All(w.ResourceLots,l=>Assert.Equal(w.NewMilitary!.Terms.Owner,l.Owner));}
    [Fact]public void PartialCollapseDoesNotPullHealthyLeadAway(){var s=Ready();var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(I(s,NewMilitaryAction.Form) with{A=new(a.X+30000,a.Y),B=new(a.X+40000,a.Y)},s.PlayerControl,s.Revision).Code);At(s,ArmyEnd(s)+1);var lead=NewGameMilitary.Position(s.DiagnosticSnapshot(),0,s.Seconds);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(RoutInput(s),s.PlayerControl,s.Revision).Code);At(s,s.Seconds+5);var w=s.DiagnosticSnapshot();Assert.DoesNotContain(w.NewMilitary!.Rout!.Retreats,t=>t.Units.Contains(0));Assert.Contains(w.NewMilitary.Rout.Retreats,t=>t.Units.Contains(1));Assert.Equal(lead,NewGameMilitary.Position(w,0,s.Seconds));var copy=new WorldSession(ContractJson.Copy(w));At(s,s.Seconds+3);At(copy,copy.Seconds+3);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(copy.DiagnosticSnapshot()));}
    [Fact]public void BlockedRoutHoldsAndLocalRecallCanRecover(){var s=Ready();var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(I(s,NewMilitaryAction.Form) with{A=new(a.X,a.Y+8000),B=new(a.X,a.Y+18000)},s.PlayerControl,s.Revision).Code);At(s,ArmyEnd(s)+1);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(RoutInput(s),s.PlayerControl,s.Revision).Code);At(s,s.Seconds+10);var w=s.DiagnosticSnapshot();Assert.Contains(w.NewMilitary!.Rout!.Retreats,t=>t.Reason.Contains("blocked"));Assert.Contains(Enumerable.Range(0,3),i=>NewGameMilitary.RoutPhase(w,i)=="rout-blocked");At(s,ArmyEnd(s)+1);Send(s,NewMilitaryAction.Recall);At(s,ArmyEnd(s)+NewGameMilitary.RegroupSeconds+1);Assert.True(NewGameMilitary.AtHome(s.DiagnosticSnapshot()));Assert.False(NewGameMilitary.RoutActive(s.DiagnosticSnapshot()));}
    [Theory][InlineData(false)][InlineData(true)]public void ForgedArrivalOrRegroupRejected(bool regroup){var s=Contact();At(s,s.Seconds+10);At(s,ArmyEnd(s)+NewGameMilitary.RegroupSeconds+1);var w=s.DiagnosticSnapshot();var r=w.NewMilitary!.Rout!;if(regroup)r.Regroups[0]=r.Regroups[0] with{Morale=100};else r.Arrivals[0]=r.Arrivals[0] with{At=r.Arrivals[0].At-1};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void UnknownMotionContractRejectedWithoutMutation(){var s=Ready();var before=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(RoutInput(s) with{MotionContract="future-unknown"},s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact]public void DelayedOldRecallDoesNotReplaceSelfPreservingRout(){var s=Ready();Send(s,NewMilitaryAction.Recall);At(s,ArmyEnd(s)+1);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(RoutInput(s),s.PlayerControl,s.Revision).Code);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);At(s,s.Seconds+9);Send(s,NewMilitaryAction.RemoteRecall);var d=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last();At(s,d.DueAt);var w=s.DiagnosticSnapshot();Assert.NotEmpty(w.NewMilitary!.Rout!.Retreats);var received=w.NewMilitary.Withdrawal!.Receipts.Last();Assert.True(received.Delivered);Assert.False(received.Applied);Assert.Equal(NewMilitaryAction.AutoRout,w.NewMilitary.Orders.Last().Action);}

}
